public class PersonController {

    /** A grade a person was given and the date it applies from (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(PersonGrade grade) {
            return new GradeView(grade.getGrade(), grade.getFrom());
        }
    }

    /** A hold put on a person: from its from-date to its to-date (null: it does not end). */
    public record HoldView(LocalDate from, LocalDate to) {
        public static HoldView of(PersonHold hold) {
            return new HoldView(hold.getFrom(), hold.getTo());
        }
    }

    /** A past retirement of a person: from the date they were retired from to the day they were unretired. */
    public record RetirementView(LocalDate from, LocalDate to) {
        public static RetirementView of(PersonRetirement retirement) {
            return new RetirementView(retirement.getFrom(), retirement.getTo());
        }
    }

    /** A SNAPSHOT written for a person: the day being left and their due-total then ("n/a" for none). */
    public record SnapshotView(LocalDate day, String dueTotal) {
        public static SnapshotView of(PersonSnapshot snapshot) {
            return new SnapshotView(snapshot.getDay(), snapshot.getDueTotal());
        }
    }

    /** A person as the screen shows them, with the grade in force on the sheet's today and every
     *  grade they were given from the earliest, how many statements were taken for them and the
     *  last one's due-total and date (null when none was), and whether they are retired and from
     *  when (null when not), and the holds put on them in the order they were, and the ids of their patrons in the order
     *  they were named, and whether the signed-in user watches them, and their own terms (null for none), and their contact (null for none), and their aliases sorted as names are compared, and the sheet they were transferred from (null for none), and their past retirements in the order they ended, and their tags sorted (empty for none), and the snapshots written for them oldest first. */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            int statementCount, String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom,
            List<HoldView> holds, List<Long> patronIds, boolean watched, Integer terms, String contact,
            List<String> aliases, boolean clashing, String origin, List<RetirementView> retirements,
            List<String> tags, List<SnapshotView> snapshots) {
        public static PersonView of(Person person, List<PersonGrade> grades, LocalDate today,
                StatementSummary statements, List<PersonHold> holds, List<Long> patronIds, boolean watched,
                List<String> aliases, boolean clashing, List<PersonRetirement> retirements,
                List<PersonSnapshot> snapshots) {
            return new PersonView(person.getId(), person.getName(), PersonGradeService.gradeOn(grades, today),
                    grades.stream().map(GradeView::of).toList(), person.getVersion(), statements.count(),
                    statements.lastDueTotal(), statements.lastDate(), person.isRetired(), person.getRetiredFrom(),
                    holds.stream().map(HoldView::of).toList(), patronIds, watched, person.getTerms(),
                    person.getContact(), aliases, clashing, person.getOriginSheetId(),
                    retirements.stream().map(RetirementView::of).toList(), person.getTags(),
                    snapshots.stream().map(SnapshotView::of).toList());
        }
    }

    /** A person's fields: a name that is not blank, a grade of A, B or C, and their own terms in whole
     *  days (null for none). */
    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            @Min(0) @Max(36500) Integer terms,
            @Size(max = 200) String contact,
            @Size(max = 2000) String tags) {
    }

    /** A person's fields as saved from an editor: the grade applies from its from-date (blank takes
     *  the sheet's today), their own terms in whole days (null for none), with the version of the person the editor loaded. */
    public record PersonUpdate(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Min(0) @Max(36500) Integer terms,
            @Size(max = 200) String contact,
            @Size(max = 2000) String tags,
            @NotNull Long version) {
    }

    /** People selected to be given a grade together: a grade of A, B or C and the date it applies from
     *  (blank takes the sheet's today). */
    public record BulkGradeRequest(
            @NotNull @Size(max = 10000) Set<@NotNull Long> personIds,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
  /** Raised on every save; an editor saves only the version it loaded. */
  version: number;
  /** The person's own terms in business days, which fix the due-by of their claims; null for none. */
  terms: number | null;
  /** The person's contact, trimmed and lower-cased; null for none. */
  contact: string | null;
  /** The person's tags, lower case and sorted; empty when they have none. */
  tags: string[];
  /** The sheet the person was transferred from; null for one not transferred in. */
  origin: string | null;
  /** How many statements were taken for the person. */
  statementCount: number;
  /** The last statement's due-total (two decimals, or n/a); null when none was taken. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null when none was. */
  statementDate: string | null;
  /** Whether the person is retired: any retirement date set counts, whatever the date. */
  retired: boolean;
  /** The date the person is retired from; null when they are not retired. */
  retiredFrom: string | null;
  /** The person's past retirements, from the date they were retired from to the day they were
   *  unretired, in the order they ended. */
  retirements: { from: string; to: string }[];
  /** The snapshots written for the person, oldest first: the day being left and their due-total
   *  then ('n/a' when none). */
  snapshots: { day: string; dueTotal: string }[];
  /** The holds put on the person, in the order they were: their OPEN claims dated within one, unless
   *  bound by a statement, count in no live total. */
  holds: Hold[];
  /** The ids of the person's patrons, in the order they were named. */
  patronIds: number[];
  /** Whether the signed-in user watches the person. */
  watched: boolean;
  /** The person's aliases, sorted as names are compared. */
  aliases: string[];
  /** Whether the person's name or an alias of theirs is a name or alias on another sheet of the tree. */
  clashing: boolean;
}

/** The figures of a sheet's descendants added up, each as that sheet shows it (as of the screen's
 *  as-of date while one is set), and the sheet's own figures likewise (absent until read). */
interface DescendantFigures {
  people: number;
  dueTotal: string;
  overdueTotal: string;
  ownPeople?: number;
  ownDueTotal?: string;
  ownOverdueTotal?: string;
}

/** What the people list can be sorted by on the screen. */
type SortKey = 'added' | 'name' | 'grade' | 'due-total';

const NO_DESCENDANTS: DescendantFigures = { people: 0, dueTotal: '0.00', overdueTotal: '0.00' };

/** A statement taken: the person's statements as their row shows them, and their claims as it
 *  bound them. */
