# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
/** Loads sheets by id; a sheet never loaded before starts empty, its today the real date. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Clock clock;
    private final Audit audit;

    public SheetService(SheetRepository sheets, Clock clock, Audit audit) {
        this.sheets = sheets;
        this.clock = clock;
        this.audit = audit;
    }

    /** The sheet with this id, created empty when it was never loaded before. */
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, LocalDate.now(clock)));
            } catch (DataIntegrityViolationException e) {
                return sheets.findById(id).orElseThrow(() -> e); // created concurrently
            }
        });
    }

    /** The sheet's today: the date every date-dependent decision and default on the sheet uses. */
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Take the sheet's next claim number, FY<year>-<n>: the one after the last given in the fiscal
     *  year (under the sheet's start month) of the date anywhere in its tree (the sheets reached
     *  through parents and children from it). Every sheet of the tree is held locked until the
     *  transaction ends so claims opened at the same moment get different numbers. */
    @Transactional
    public String nextClaimNumber(String id, LocalDate date) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        int fiscalYear = sheet.fiscalYearOf(date);
        long lastInTree = 0;
        for (String other : treeOf(id)) {
            if (!other.equals(id)) {
                lastInTree = Math.max(lastInTree,
                        sheets.findLockedById(other).map(s -> s.getLastClaimNumber(fiscalYear)).orElse(0L));
            }
        }
        long number = sheet.takeClaimNumberAfter(fiscalYear, lastInTree);

